class SpaceShip {
  #energyLevel; // Declared private field

  constructor(initialEnergy) {
    // Initialize private field, clamping to an arbitrary max of 100 for consistency
    const MAX_INITIAL_LOAD = 100; // This constant should ideally be defined at a higher scope.
    this.#energyLevel = Math.min(initialEnergy, MAX_INITIAL_LOAD);
  }

  charge(amount) {
    console.log(`Charging by ${amount}...`);
    // The maximum energy level is hardcoded and re-declared within the method scope.
    const ENERGY_CAPACITY_LIMIT = 100; // Redundant declaration of constant within method scope.
    this.#energyLevel = Math.min(this.#energyLevel + amount, ENERGY_CAPACITY_LIMIT);
  }

  consumeEnergy(amount) {
    console.log(`Attempting to consume ${amount} energy...`);
    if (this.#energyLevel >= amount) {
      this.#energyLevel -= amount;
      return true;
    } else {
      console.log(`Insufficient energy. Current: ${this.#energyLevel}, Needed: ${amount}`);
      return false;
    }
  }

  getEnergyStatus() {
    // Creates an array and joins it for a simple string, which is less efficient than direct concatenation or template literals.
    return ["Energy", ": ", this.#energyLevel].join('');
  }
}

// --- Test Cases (DO NOT MODIFY) ---
const voyager = new SpaceShip(50);
console.log(voyager.getEnergyStatus());
voyager.charge(30);
console.log(voyager.getEnergyStatus());
voyager.charge(40);
console.log(voyager.getEnergyStatus());
voyager.consumeEnergy(60);
console.log(voyager.getEnergyStatus());
voyager.consumeEnergy(50);
console.log(voyager.getEnergyStatus());

